<?php $pageTitle='Reviews';$theme='pink';require_once 'includes/db.php';$success='';if($_SERVER['REQUEST_METHOD']==='POST'){$vendor=(int)$_POST['vendor_id'];$name=trim($_POST['name']);$rating=min(5,max(1,(int)$_POST['rating']));$review=trim($_POST['review']);if($vendor&&$name&&$review){$q=$pdo->prepare("INSERT INTO reviews(vendor_id,name,rating,review) VALUES(?,?,?,?)");$q->execute([$vendor,$name,$rating,$review]);$success='Thank you. Your review is waiting for admin approval.';}}$vendors=$pdo->query('SELECT id,name FROM vendors WHERE active=1 ORDER BY name')->fetchAll();include 'includes/header.php';?><section class="py-5"><div class="container"><div class="col-lg-7 mx-auto content-card p-4 p-md-5"><h2>Share your experience</h2><?php if($success):?><div class="alert alert-success"><?=htmlspecialchars($success)?></div><?php endif;?><form method="post" class="row g-3"><div class="col-12"><label class="form-label">Vendor</label><select name="vendor_id" class="form-select" required><?php foreach($vendors as $v):?><option value="<?=$v['id']?>"><?=htmlspecialchars($v['name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Your Name</label><input name="name" class="form-control" required></div><div class="col-md-6"><label class="form-label">Rating</label><select name="rating" class="form-select"><option>5</option><option>4</option><option>3</option><option>2</option><option>1</option></select></div><div class="col-12"><textarea name="review" rows="4" class="form-control" placeholder="How was your experience?" required></textarea></div><div class="col-12"><button class="btn btn-brand">Submit Review</button></div></form></div></div></section><?php include 'includes/footer.php'; ?>
